package com.inventra.backend.service; import com.inventra.backend.dto.*; import com.inventra.backend.model.Product; import com.inventra.backend.repository.ProductRepository; import org.springframework.stereotype.Service; import java.util.*; @Service public class InventoryAssistantService {private final ProductRepository products;private final AlertService alerts;public InventoryAssistantService(ProductRepository p,AlertService a){products=p;alerts=a;}public AssistantResponse ask(String q){String x=q.toLowerCase();if(x.contains("low")||x.contains("stock")){List<Product> low=products.findLowStockProducts();return new AssistantResponse("There are "+low.size()+" products at or below their reorder level. Review the Low Stock and Replenishment views for action.","LOW_STOCK");}if(x.contains("product")||x.contains("inventory")){return new AssistantResponse("Inventra currently manages "+products.count()+" products. I can help with stock levels, replenishment, orders, returns, and alerts.","INVENTORY");}return new AssistantResponse("I can help you analyze inventory, low stock, replenishment, orders, returns, and demand forecasts. Try asking: Which products are low in stock?","GENERAL");}}
